import random
random.seed(11)
B, D, M = 2, 3, 2

def matmul(A, Bc):
    return [[sum(A[i][k] * Bc[k][j] for k in range(len(Bc))) for j in range(len(Bc[0]))] for i in range(len(A))]

def transpose(A):
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]

def dot_all(A, Bc):
    return sum(A[i][j] * Bc[i][j] for i in range(len(A)) for j in range(len(A[0])))

X = [[random.uniform(-1, 1) for _ in range(D)] for _ in range(B)]
W = [[random.uniform(-1, 1) for _ in range(M)] for _ in range(D)]
Y_bar = [[random.uniform(-1, 1) for _ in range(M)] for _ in range(B)]

W_bar = matmul(transpose(X), Y_bar)
X_bar = matmul(Y_bar, transpose(W))
b_bar = [sum(Y_bar[i][j] for i in range(B)) for j in range(M)]

h = 1e-6
def surrogate(dW=None, dX=None, db=None):
    W2 = [row[:] for row in W]
    X2 = [row[:] for row in X]
    if dW:
        i, j, v = dW
        W2[i][j] += v
    if dX:
        i, j, v = dX
        X2[i][j] += v
    P = matmul(X2, W2)
    off = db if db else [0.0] * M
    return dot_all([[P[i][j] + off[j] for j in range(M)] for i in range(B)], Y_bar)

for i in range(D):
    for j in range(M):
        num = (surrogate(dW=(i, j, h)) - surrogate(dW=(i, j, -h))) / (2 * h)
        assert abs(num - W_bar[i][j]) < 1e-4, (num, W_bar[i][j])
for i in range(B):
    for j in range(D):
        num = (surrogate(dX=(i, j, h)) - surrogate(dX=(i, j, -h))) / (2 * h)
        assert abs(num - X_bar[i][j]) < 1e-4, (num, X_bar[i][j])
for j in range(M):
    plus = [h if k == j else 0.0 for k in range(M)]
    minus = [-h if k == j else 0.0 for k in range(M)]
    num = (surrogate(db=plus) - surrogate(db=minus)) / (2 * h)
    assert abs(num - b_bar[j]) < 1e-4, (num, b_bar[j])
